WITH car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm,a.area FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.id_imovel='BA-2929701-3438EBE3EC1C4160B13A7DC99112E048' AND a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(a.id_imovel,'-','') ORDER BY a.data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm,cpf,cnpj_basico FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),mut AS (SELECT DISTINCT id_referencia_bacen,cpf,cnpj FROM `basedosdados.br_bcb_sicor.recurso_publico_mutuario` WHERE ano_emissao BETWEEN 2013 AND 2026),x AS (SELECT p.ano_emissao,p.id_referencia_bacen,p.numero_ordem,COALESCE(NULLIF(p.cpf,''),NULLIF(p.cnpj_basico,'')) proprietario,COALESCE(NULLIF(mut.cpf,''),NULLIF(mut.cnpj,'')) mutuariodoc FROM p JOIN car USING(id_car_norm) LEFT JOIN mut USING(id_referencia_bacen)),op AS (SELECT id_referencia_bacen,COUNT(DISTINCT COALESCE(proprietario,mutuariodoc)) docs,COUNT(DISTINCT proprietario) proprietarios,COUNT(DISTINCT mutuariodoc) mutuarios FROM x GROUP BY 1),bydoc AS (SELECT COALESCE(proprietario,mutuariodoc) doc,COUNT(DISTINCT id_referencia_bacen) n_operacoes,COUNT(DISTINCT ano_emissao) n_anos FROM x WHERE COALESCE(proprietario,mutuariodoc) IS NOT NULL GROUP BY 1) SELECT COUNT(*) operacoes,COUNTIF(docs>1) operacoes_com_varios_documentos,MAX(docs) max_documentos_por_operacao,MAX(proprietarios) max_proprietarios_por_operacao,MAX(mutuarios) max_mutuarios_por_operacao,(SELECT COUNT(*) FROM bydoc) documentos,(SELECT MAX(n_operacoes) FROM bydoc) max_operacoes_por_documento,(SELECT MAX(n_anos) FROM bydoc) max_anos_por_documento FROM op